import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BAQ5ZYJQ.js";const k=JSON.parse('{"title":"Every run, live in the browser","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web.md","filePath":"guide/web.md","lastUpdated":1795160929000}'),n={name:"guide/web.md"};function h(r,e,o,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="every-run-live-in-the-browser" tabindex="-1">Every run, live in the browser <a class="header-anchor" href="#every-run-live-in-the-browser" aria-label="Permalink to &quot;Every run, live in the browser&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lmo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # -O, --open: the run&#39;s page opens in the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                  # every run of every machine, as a page</span></span></code></pre></div><p>Each run has a page, and it is live: the console as the program writes it, its step and progress bar, its curves, its images and HTML pages redrawn as the run writes them, wherever it runs. No <code>scp</code> to look at a figure, no <code>tail -f</code> over ssh: the page follows the run, and stays once it ends.</p><p><code>errand web</code> is the same for everything: what runs on every machine you sent work to, what waits, every run done as a tree with a table of its parameters and results, the machines&#39; gauges, the library caches they hold. Pick a run, and its page is on the right.</p><p>Neither one runs anything itself. What runs is owned by the agents over there: close the tab, nothing stops. Nothing is asked again and again either: the agents say what changes, when it changes, and the page shows it at once.</p><h2 id="a-run-s-page" tabindex="-1">A run&#39;s page <a class="header-anchor" href="#a-run-s-page" aria-label="Permalink to &quot;A run&#39;s page&quot;">​</a></h2><p><code>errand run</code> prints, under each run&#39;s head, the address of its page; <code>-O</code> ( <code>--open</code> ) opens it in the browser by itself, a tab per run for the first few, then the main page:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ▸ train  lin  lmo</span></span>
<span class="line"><span>    ↗ http://127.0.0.1:20501/r/3f2a9c1e</span></span></code></pre></div><p>What it shows, as it happens:</p><ul><li><strong>the console</strong>, stdout and stderr, as the program writes them;</li><li><strong>where the run is</strong>: the text and bar of its last <a href="./steps">step</a>, the estimated end, how long since the last step ( a run that hangs shows ), a curve per value it reports;</li><li><strong>its views</strong>: the files it names with <a href="./steps#view-a-file-that-evolves"><code>errand.view</code></a>, an image, an SVG, an HTML page, brought back from the machine that runs it as soon as they change, and shown in place. A directory that carries its own page ( <code>errand.Static</code> ) is served as it is, while the run is still writing it;</li><li><strong>its files</strong> once it ends: <code>output.txt</code>, <code>result.yaml</code>, what it wrote in its directory.</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> it </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( n_iter ):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    errand.step( </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;iteration </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">done</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> it </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n_iter, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">loss</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loss )</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> it </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        plot_mesh( mesh, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mesh.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        errand.view( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mesh.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">title</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;current mesh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># on the page a moment later</span></span></code></pre></div><p>The address holds no secret, and works for a run on any machine: the page is served by this machine&#39;s agent, which asks the others.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><p>Tab <code>1</code>. What runs and what waits on top, then every run done, as a tree:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>otrec/</span></span>
<span class="line"><span>  experiments/exp_2d_real.py</span></span>
<span class="line"><span>    foam</span></span>
<span class="line"><span>        n      nb_splits reduction | loss   status  when     runs</span></span>
<span class="line"><span>        10000  1         1         | 0.005  PASS    12:13    34</span></span>
<span class="line"><span>        2000   1         8         | 0.002  PASS    12:14    1</span></span>
<span class="line"><span>          ▸ its runs: date, machine, env, status, duration</span></span>
<span class="line"><span>sdot-ffi/</span></span>
<span class="line"><span>  …</span></span></code></pre></div><ul><li><strong>The tree</strong> is the path of the file from the project&#39;s root, the file, the entry, then its <strong>parameter sets</strong>: the runs whose parameters are equal, whatever machine or environment.</li><li><strong>The table</strong> has a column per parameter, then the results the run declared, the status and date of the last run, how many runs. <code>s</code> sorts by the next column.</li><li><strong>Removing</strong>: <code>d</code> removes the runs under the row, <code>D</code> keeps only the latest of each set and environment, after a confirmation. <code>⇧↑ ⇧↓</code> chooses several rows.</li><li><strong>Runs elsewhere</strong>: the list is this machine&#39;s record ( every run started from here has its directory here ). <code>c</code> checks the other machines for runs not here ( <code>◇</code> ), <code>b</code> brings one back.</li></ul><h2 id="the-detail" tabindex="-1">The detail <a class="header-anchor" href="#the-detail" aria-label="Permalink to &quot;The detail&quot;">​</a></h2><p>Right of the list, the row chosen: its run&#39;s page ( above ), its facts, its views and outputs. The output chosen is shown below them, text, image or HTML, and opens whole in a tab of its own. A row can also be killed, through every layer, once confirmed.</p><h2 id="machines" tabindex="-1">Machines <a class="header-anchor" href="#machines" aria-label="Permalink to &quot;Machines&quot;">​</a></h2><p>Tab <code>2</code>. Each machine of the ledger: its gauges ( CPUs, memory, cards ), measured only while shown, what holds it, its VMs and guests, what is kept warm. <code>a</code> watches a machine or not, <code>r</code> gives it a name, <code>f</code> forgets it until work is sent there again.</p><h2 id="caches" tabindex="-1">Caches <a class="header-anchor" href="#caches" aria-label="Permalink to &quot;Caches&quot;">​</a></h2><p>Tab <code>3</code>. The <a href="./caching#a-library-s-caches-kept-tidy">library caches</a> of every machine: per cache, a row per place, then its entries merged across places, with their size and when they last served.</p><ul><li><code>i</code> removes the dead entries, <code>u</code> those unused for n days ( <code>n</code> sets n, 30 by default ), of one place or, on a cache&#39;s row, of every place;</li><li><code>d</code> removes the entry under the cursor where it is dead or unused, <code>D</code> everywhere it is;</li><li><code>h</code> has the place&#39;s machine hold the directory: its agent purges it daily;</li><li><code>v</code> shows every entry, or only the dead and unused.</li></ul><h2 id="from-another-machine" tabindex="-1">From another machine <a class="header-anchor" href="#from-another-machine" aria-label="Permalink to &quot;From another machine&quot;">​</a></h2><p><code>errand web</code> opens the page in the browser and prints its address. It is served by this machine&#39;s host agent, on <code>127.0.0.1</code> only, one per user and machine. The port is open to every user of the machine, so the page is served only to who holds a token: <code>errand web</code> opens it with a code used once, then a cookie keeps it. <code>errand web token</code> prints the token, for another browser.</p><p>From another machine, a tunnel:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 20501:localhost:20501</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lmo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # then errand web there gives the URL</span></span></code></pre></div><h2 id="the-same-in-the-terminal-errand-tui" tabindex="-1">The same in the terminal: errand tui <a class="header-anchor" href="#the-same-in-the-terminal-errand-tui" aria-label="Permalink to &quot;The same in the terminal: errand tui&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><p>The same tabs, the same tree and detail, in curses, for a session with no browser. <code>w</code> opens the run under the cursor in the browser.</p><table tabindex="0"><thead><tr><th>key</th><th></th></tr></thead><tbody><tr><td><code>1</code> <code>2</code> <code>3</code></td><td>runs, machines, caches</td></tr><tr><td><code>↑ ↓</code> <code>pgup pgdn</code></td><td>move · <code>→ ←</code> unfold, fold · <code>tab</code> the list or the detail</td></tr><tr><td><code>enter</code></td><td>open an output as this machine opens it · <code>e</code> in <code>$EDITOR</code> · <code>o</code> in <code>$PAGER</code> · <code>w</code> the run&#39;s page</td></tr><tr><td><code>/</code></td><td>filter: machine, project, command, state · <code>p</code> this project or all</td></tr><tr><td><code>k</code></td><td>kill, once confirmed · <code>x</code> a shell on its machine, where it works</td></tr><tr><td><code>R</code></td><td>ask every machine again now</td></tr><tr><td><code>?</code></td><td>every key · <code>q</code> leave, nothing stops</td></tr></tbody></table><p>The page takes the same keys, with buttons beside them.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./status">What is running</a> · <a href="./steps">Where a run is: steps</a> · <a href="./caching">Data and results, computed once</a></p>`,34)])])}const g=s(n,[["render",h]]);export{k as __pageData,g as default};
